function playInPageStream(streamUrl, serverNum) { const playerScreen = document.getElementById('heroPlayerScreen'); const stageContent = document.getElementById('heroStageContent'); const video = document.getElementById('liveVideoElement'); const iframe = document.getElementById('livePlayerIframe'); const loader = document.getElementById('playerLoadingOverlay'); const noticeOverlay = document.getElementById('playerNoticeOverlay'); const tab1 = document.getElementById('tabServer1'); const tab2 = document.getElementById('tabServer2');
