if (titleEl) titleEl.innerText = titleText || activePostTitle || "Pertandingan Mendatang"; if (badgeEl) { badgeEl.innerHTML = isUpcoming ? "<i class='fa-regular fa-clock'></i> JADWAL SIARAN" : "<i class='fa-solid fa-satellite-dish'></i> STATUS PEMANCAR"; } if (subEl) { subEl.innerText = isUpcoming ? "Pertandingan dijadwalkan pukul " + (kickoffText || "hari ini") + ". Siaran langsung akan otomatis aktif sesaat sebelum laga dimulai." : "Sedang menunggu sinyal siaran dari pemancar lapangan. Silakan klik Refresh atau coba Server 2."; } } }
function startHls(hlsUrl, isFallback) { if (window.Hls && Hls.isSupported()) { hlsInstance = new Hls({ enableWorker: true, lowLatencyMode: true, backBufferLength: 0, maxBufferLength: 8, maxMaxBufferLength: 16, manifestLoadingTimeOut: 3000, manifestLoadingMaxRetry: 1 }); hlsInstance.loadSource(hlsUrl); hlsInstance.attachMedia(video); hlsInstance.on(Hls.Events.MANIFEST_PARSED, function() { executePlay(); }); hlsInstance.on(Hls.Events.ERROR, function(event, data) { if (data.fatal) { if (!isFallback) { console.warn('HLS failover ke HLS Backup...'); startHls(endpoints.hls2, true); } else { console.warn('HLS failover ke FLV...'); startFlv(endpoints.flv1, false); } } }); } else if (video.canPlayType('application/vnd.apple.mpegurl')) { video.src = hlsUrl; executePlay(); } }
