flvPlayerInstance.on(flvjs.Events.ERROR, function() { if (!isFallback) { startFlv(endpoints.flv2, true); } else { startHls(endpoints.hls1, false); } }); } catch (e) { if (!isFallback) startHls(endpoints.hls1, false); } }
// Launch player immediately with requested server if (serverNum === 2) { startFlv(endpoints.flv1, false); } else { startHls(endpoints.hls1, false); }
