function createMatchSlug(title) { if (!title) return ''; return encodeURIComponent( title.toLowerCase() .trim() .replace(/[^a-z0-9]+/g, '-') .replace(/^-+|-+$/g, '') ); }
function getMatchUrl(title) { const slug = createMatchSlug(title); const origin = window.location.origin || (window.location.protocol + '//' + window.location.host); const pathname = window.location.pathname || ''; return origin + pathname + '#' + slug; }
function updateUrlForMatch(title) { const slug = createMatchSlug(title); if (slug) { const newHash = '#' + slug; if (window.location.hash !== newHash) { if (window.history && window.history.replaceState) { window.history.replaceState(null, '', newHash); } else { window.location.hash = newHash; } } } }
