function copyTextToClipboard(text, message) { if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(text).then(function() { showCopyToast(message || 'Link berhasil disalin!'); }).catch(function() { fallbackCopyText(text, message); }); } else { fallbackCopyText(text, message); } }
function fallbackCopyText(text, message) { var temp = document.createElement('input'); temp.value = text; document.body.appendChild(temp); temp.select(); try { document.execCommand('copy'); showCopyToast(message || 'Link berhasil disalin!'); } catch (e) {} document.body.removeChild(temp); }
function showCopyToast(msg) { var toast = document.getElementById('copyToastNotification'); if (!toast) { toast = document.createElement('div'); toast.id = 'copyToastNotification'; toast.style.cssText = 'position:fixed; bottom:24px; right:24px; background:#10b981; color:#fff; padding:12px 20px; border-radius:10px; font-weight:700; font-size:13px; z-index:99999; box-shadow:0 8px 24px rgba(0,0,0,0.5); display:flex; align-items:center; gap:8px; transition:opacity 0.3s ease;'; document.body.appendChild(toast); } toast.innerHTML = '<i class="fa-solid fa-circle-check"></i> ' + msg; toast.style.opacity = '1'; toast.style.display = 'flex'; setTimeout(function() { toast.style.opacity = '0'; setTimeout(function() { toast.style.display = 'none'; }, 300); }, 2500); }
