// 5. TERAPKAN PERTANDINGAN KE HERO BROADCAST STAGE function applyMatchToPlayer(title, streamUrl, server2Url, kickoffIso, kickoffText, league) { activeStreamUrlServer1 = streamUrl || ""; activeStreamUrlServer2 = server2Url || ""; activePostTitle = title || "";
const heroTitle = document.getElementById('heroMatchTitle'); const heroLeague = document.getElementById('heroLeagueBadge'); const heroKickoff = document.getElementById('heroKickoffLabel'); const heroHome = document.getElementById('heroHomeTeam'); const heroAway = document.getElementById('heroAwayTeam'); const playerScreen = document.getElementById('heroPlayerScreen');
