if (diff > 0) { const totalSec = Math.floor(diff / 1000); const h = String(Math.floor(totalSec / 3600)).padStart(2, '0'); const m = String(Math.floor((totalSec % 3600) / 60)).padStart(2, '0'); const s = String(totalSec % 60).padStart(2, '0'); badge.innerText = h + 'h : ' + m + 'm : ' + s + 's'; badge.style.color = "var(--primary)"; } else if (diff >= -9000000) { badge.innerHTML = '<i class="fa-solid fa-circle" style="font-size:7px; animation:blink 1s infinite;"></i> LIVE NOW'; badge.style.color = "var(--accent-live)"; } else { badge.innerText = 'SELESAI'; badge.style.color = "var(--text-dim)"; } } } });
// Update in-player countdown if visible const noticeCd = document.getElementById('playerNoticeCountdown'); if (noticeCd) { if (activeMatchDiff !== null && activeMatchDiff > 0) { const totalSec = Math.floor(activeMatchDiff / 1000); const h = String(Math.floor(totalSec / 3600)).padStart(2, '0'); const m = String(Math.floor((totalSec % 3600) / 60)).padStart(2, '0'); const s = String(totalSec % 60).padStart(2, '0'); noticeCd.innerText = h + 'h : ' + m + 'm : ' + s + 's'; } else if (activeMatchDiff !== null && activeMatchDiff <= 0) { noticeCd.innerText = 'SIARAN SEDANG BERLANGSUNG'; } } }, 1000); }
function parseTimestampToMs(isoStr, textStr) { if (isoStr) { const t = new Date(isoStr).getTime(); if (!isNaN(t)) return t; } if (textStr) { const match = textStr.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})[,\s]+(\d{1,2})[:\.](\d{2})/); if (match) { const day = match[1].padStart(2, '0'); const month = match[2].padStart(2, '0'); const year = match[3]; const hour = match[4].padStart(2, '0'); const min = match[5].padStart(2, '0'); const parsedIso = year + '-' + month + '-' + day + 'T' + hour + ':' + min + ':00+07:00'; const t = new Date(parsedIso).getTime(); if (!isNaN(t)) return t; } } return 0; }
// 6. PROCESS, FILTER & SORT ENGINE // - Status 0 (🔴 SEDANG LIVE): PALING ATAS // - Status 1 (⏳ MENUNGGU): DI BAWAHNYA, DIURUTKAN DARI JAM KICKOFF TERDEKAT // - Status 2 (🏁 SELESAI): PALING BAWAH (TIDAK HILANG, TETAP BISA DILIHAT) function processAndSortMatches(rawMatches) { const now = new Date().getTime(); const validMatches = []; const seenTitles = new Set();
