// ATURAN STATUS TEPAT DARI WEB SUMBER: // StatusAttr 2, 3, 4, 5, 17, 53, 432 = 🔴 SEDANG LIVE (0) // StatusAttr 6, 8 = 🏁 SELESAI (2) // StatusAttr 1 = ⏳ MENUNGGU (1) let status = 1; if (typeof m.status === 'number') { status = m.status; } else if (statusAttr) { const num = parseInt(statusAttr, 10); if (num === 6 || num === 8) { status = 2; // Selesai } else if (num >= 2 && num <= 5 || num > 8) { status = 0; // Sedang Live } else if (num === 1) { if (kickoffTime && now >= kickoffTime && (now - kickoffTime) <= 10800000) { status = 0; // Kickoff sudah dimulai dalam 3 jam terakhir } else if (kickoffTime && (now - kickoffTime) > 10800000) { status = 2; // Lewat 3 jam } else { status = 1; // Menunggu } } } else if (kickoffTime) { if (diff <= 0 && diff >= -10800000) { status = 0; // Sedang Live (dalam durasi 3 jam) } else if (diff < -10800000) { status = 2; // Selesai } else { status = 1; // Menunggu } } else { status = 0; }
