// URUTKAN: // 1. Sedang LIVE (status 0) PALING ATAS // 2. Menunggu (status 1) di bawahnya, diurutkan kronologis (jam kickoff terdekat pertama) // 3. Selesai (status 2) di paling bawah validMatches.sort((a, b) => { if (a.status !== b.status) { return a.status - b.status; } if (a.status === 0) { return a.kickoffTime - b.kickoffTime; } if (a.status === 1) { return a.kickoffTime - b.kickoffTime; } return b.kickoffTime - a.kickoffTime; });
